1	<?php
2	
3	/**
4	 * Push-webhook receiver for the static marketing site.
5	 *
6	 * The content pages (this `public/` directory) can be hosted at the apex domain
7	 * separately from the app container. This is meant for generic web hosting that
8	 * can serve PHP and run git over SSH, but cannot run a persistent listener.
9	 * Deploys are pull-based: GitHub POSTs here on every push, this script verifies
10	 * the HMAC signature and fast-forwards the on-disk checkout.
11	 *
12	 * Setup (one-time, over SSH on the marketing host) is documented in
13	 * docs/split-hosting.md. In short:
14	 *   - clone the repo somewhere outside the served web directory
15	 *   - point the domain's web directory at the repo's `public/` folder
16	 *   - write the shared secret to `.deploy-secret` in the REPO ROOT (one dir up
17	 *     from this file — outside the web directory, and .gitignored)
18	 *   - add a GitHub webhook → https://www.hisohiso.org/_deploy.php, content-type
19	 *     application/json, secret = the same value, events = "push"
20	 *
21	 * Security model: the endpoint is public (GitHub must reach it), so it does
22	 * nothing until it sees a valid X-Hub-Signature-256 over the raw body. Anything
23	 * unsigned/forged gets a flat 404 — no hint that a deploy hook lives here.
24	 */
25	
26	declare(strict_types=1);
27	
28	// The git checkout root is the parent of this web directory (docroot = public/).
29	$repoDir = realpath(__DIR__ . '/..');
30	$branch  = getenv('HISOHISO_DEPLOY_BRANCH') ?: 'main';
31	$logFile = $repoDir . '/.deploy.log';
32	
33	// Secret: prefer an env var (e.g. SetEnv in .htaccess), else a file in the repo
34	// root that lives OUTSIDE the served docroot and is gitignored.
35	$secret = getenv('HISOHISO_DEPLOY_SECRET') ?: '';
36	if ($secret === '') {
37	    $secretFile = $repoDir . '/.deploy-secret';
38	    if (is_readable($secretFile)) {
39	        $secret = trim((string) file_get_contents($secretFile));
40	    }
41	}
42	
43	/** Log a line and exit with an HTTP status. Never echoes the secret. */
44	function done(int $status, string $message, string $logFile): never
45	{
46	    http_response_code($status);
47	    $ts = gmdate('c');
48	    @file_put_contents($logFile, "[$ts] HTTP $status — $message\n", FILE_APPEND);
49	    // Deliberately terse to callers; detail goes to the log only.
50	    echo $status >= 200 && $status < 300 ? "ok\n" : "no\n";
51	    exit;
52	}
53	
54	// Fail closed if the deploy isn't configured, but stay silent to the world.
55	if ($secret === '') {
56	    done(404, 'no secret configured', $logFile);
57	}
58	
59	if (($_SERVER['REQUEST_METHOD'] ?? 'GET') !== 'POST') {
60	    done(404, 'not a POST', $logFile);
61	}
62	
63	$event = $_SERVER['HTTP_X_GITHUB_EVENT'] ?? '';
64	$body  = file_get_contents('php://input');
65	if ($body === false || $body === '') {
66	    done(404, 'empty body', $logFile);
67	}
68	
69	// Verify HMAC-SHA256 (`sha256=<hex>`), constant-time.
70	$sigHeader = $_SERVER['HTTP_X_HUB_SIGNATURE_256'] ?? '';
71	$expected  = 'sha256=' . hash_hmac('sha256', $body, $secret);
72	if ($sigHeader === '' || !hash_equals($expected, $sigHeader)) {
73	    done(404, 'bad signature', $logFile);
74	}
75	
76	// Signature is valid from here on.
77	if ($event === 'ping') {
78	    done(200, 'pong', $logFile);
79	}
80	if ($event !== 'push') {
81	    done(204, "ignored event: $event", $logFile);
82	}
83	
84	$payload = json_decode($body, true);
85	$ref     = is_array($payload) ? ($payload['ref'] ?? '') : '';
86	if ($ref !== "refs/heads/$branch") {
87	    done(204, "ignored ref: $ref", $logFile);
88	}
89	
90	// Some web hosts disable exec — fail loudly in the log if so.
91	if (!function_exists('shell_exec')) {
92	    done(500, 'shell_exec disabled — use the cron-poll fallback', $logFile);
93	}
94	
95	// Fast-forward the checkout to the pushed commit. reset --hard also applies
96	// tracked-file deletions, so removed pages disappear. Untracked files are left
97	// alone (a content checkout shouldn't have any).
98	$git = 'git -C ' . escapeshellarg($repoDir);
99	$cmd = "$git fetch --prune origin " . escapeshellarg($branch) . ' 2>&1'
100	     . " && $git reset --hard " . escapeshellarg("origin/$branch") . ' 2>&1';
101	$output = shell_exec($cmd) ?? '';
102	
103	@file_put_contents($logFile, "[" . gmdate('c') . "] deploy $branch:\n$output\n", FILE_APPEND);
104	
105	if (!str_contains($output, 'HEAD is now at')) {
106	    done(500, 'git failed (see .deploy.log)', $logFile);
107	}
108	
109	done(200, 'deployed', $logFile);
